document.addEventListener('DOMContentLoaded', function () {
const navToggle = document.querySelector('.nav-toggle');
const navMenu = document.querySelector('.nav-menu');
if (navToggle && navMenu) {
navToggle.addEventListener('click', function () {
const isExpanded = navMenu.classList.toggle('active');
navToggle.setAttribute('aria-expanded', isExpanded);
});
document.addEventListener('click', function (event) {
const isClickInsideNav = navToggle.contains(event.target) || navMenu.contains(event.target);
if (!isClickInsideNav && navMenu.classList.contains('active')) {
navMenu.classList.remove('active');
navToggle.setAttribute('aria-expanded', 'false');
}
});
}
const navbar = document.querySelector('.navbar');
let lastScroll = 0;
let ticking = false;
function updateNavbar() {
const currentScroll = window.pageYOffset;
if (currentScroll > 30) {
navbar.classList.add('scrolled');
} else {
navbar.classList.remove('scrolled');
}
const opacity = Math.min(0.95 + (currentScroll / 1000), 0.99);
navbar.style.setProperty('--scroll-opacity', opacity);
lastScroll = currentScroll;
ticking = false;
}
window.addEventListener('scroll', function () {
if (!ticking) {
window.requestAnimationFrame(updateNavbar);
ticking = true;
}
});
const currentPath = window.location.pathname;
const navLinks = document.querySelectorAll('.nav-menu a');
navLinks.forEach(link => {
if (link.getAttribute('href') === currentPath ||
(currentPath === '/' && link.getAttribute('href') === '/')) {
link.classList.add('active');
}
});
function createRipple(event) {
const button = event.currentTarget;
const rect = button.getBoundingClientRect();
const size = Math.max(rect.width, rect.height);
const x = event.clientX - rect.left - size / 2;
const y = event.clientY - rect.top - size / 2;
const ripple = document.createElement('span');
ripple.classList.add('ripple');
ripple.style.width = ripple.style.height = size + 'px';
ripple.style.left = x + 'px';
ripple.style.top = y + 'px';
button.appendChild(ripple);
setTimeout(() => {
ripple.remove();
}, 600);
}
document.querySelectorAll('.btn').forEach(button => {
button.addEventListener('click', createRipple);
});
document.querySelectorAll('.btn-primary, .btn-secondary, .btn-link').forEach(button => {
button.addEventListener('click', function () {
const buttonText = this.textContent.trim() || this.querySelector('span')?.textContent.trim() || 'CTA Button';
const href = this.getAttribute('href') || '';
if (typeof gtag !== 'undefined') {
gtag('event', 'click', {
'event_category': 'CTA',
'event_label': buttonText,
'value': href
});
}
if (typeof plausible !== 'undefined') {
plausible('CTA Click', { props: { button: buttonText, href: href } });
}
});
});
const observerOptions = {
threshold: 0.1,
rootMargin: '0px 0px -50px 0px'
};
const observer = new IntersectionObserver(function (entries) {
entries.forEach(entry => {
if (entry.isIntersecting) {
entry.target.classList.add('visible');
observer.unobserve(entry.target);
}
});
}, observerOptions);
const animatedElements = document.querySelectorAll('.slide-up, .feature-card, .service-card, .solution-card, .use-case-item');
animatedElements.forEach((el, index) => {
el.classList.add('slide-up');
el.style.transitionDelay = `${index * 0.1}s`;
observer.observe(el);
});
const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (!prefersReducedMotion) {
const textRevealElements = document.querySelectorAll('h1:not(.hero h1), h2:not(.hero h2), h3:not(.hero h3), .logos-intro, .customer-logos-placeholder');
const textObserver = new IntersectionObserver(function (entries) {
entries.forEach(entry => {
if (entry.isIntersecting) {
if (entry.target.classList.contains('logos-intro') || entry.target.classList.contains('customer-logos-placeholder')) {
entry.target.classList.add('animate-text-reveal');
} else {
entry.target.style.opacity = '1';
entry.target.style.transform = 'translateY(0)';
}
textObserver.unobserve(entry.target);
}
});
}, observerOptions);
textRevealElements.forEach((el, index) => {
if (!el.closest('.hero')) {
if (!el.classList.contains('logos-intro') && !el.classList.contains('customer-logos-placeholder')) {
el.style.opacity = '0';
el.style.transform = 'translateY(20px)';
el.style.transition = 'opacity 0.6s ease-out, transform 0.6s ease-out';
el.style.transitionDelay = `${Math.min(index * 0.05, 0.5)}s`;
}
textObserver.observe(el);
}
});
const staggerLists = document.querySelectorAll('.stagger-list');
const staggerObserver = new IntersectionObserver(function (entries) {
entries.forEach(entry => {
if (entry.isIntersecting) {
entry.target.classList.add('visible');
staggerObserver.unobserve(entry.target);
}
});
}, observerOptions);
staggerLists.forEach(list => {
staggerObserver.observe(list);
});
}
const backToTopButton = document.getElementById('back-to-top');
if (backToTopButton) {
window.addEventListener('scroll', function () {
if (window.pageYOffset > 300) {
backToTopButton.classList.add('visible');
} else {
backToTopButton.classList.remove('visible');
}
});
backToTopButton.addEventListener('click', function () {
window.scrollTo({
top: 0,
behavior: 'smooth'
});
});
}
const contactForm = document.querySelector('.contact-form');
if (contactForm) {
contactForm.addEventListener('submit', function (event) {
const name = document.getElementById('name');
const email = document.getElementById('email');
const message = document.getElementById('message');
let isValid = true;
document.querySelectorAll('.error-message').forEach(el => el.remove());
document.querySelectorAll('.form-group input, .form-group textarea').forEach(el => {
el.classList.remove('error');
});
if (!name.value.trim()) {
showError(name, 'Name is required');
isValid = false;
}
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email.value.trim()) {
showError(email, 'Email is required');
isValid = false;
} else if (!emailRegex.test(email.value)) {
showError(email, 'Please enter a valid email address');
isValid = false;
}
if (!message.value.trim()) {
showError(message, 'Message is required');
isValid = false;
}
if (!isValid) {
event.preventDefault();
} else {
if (typeof gtag !== 'undefined') {
gtag('event', 'form_submit', {
'event_category': 'Contact',
'event_label': 'Contact Form'
});
}
if (typeof plausible !== 'undefined') {
plausible('Contact Form Submission');
}
contactForm.style.opacity = '0.7';
setTimeout(() => {
contactForm.style.opacity = '1';
}, 100);
}
});
const formInputs = contactForm.querySelectorAll('input, textarea');
formInputs.forEach(input => {
const formGroup = input.closest('.form-group');
if (formGroup && !formGroup.classList.contains('floating-label')) {
formGroup.classList.add('floating-label');
const label = formGroup.querySelector('label');
if (label && input.id) {
const labelFor = label.getAttribute('for');
if (labelFor === input.id) {
input.insertAdjacentElement('afterend', label);
}
}
}
input.addEventListener('focus', function () {
this.parentElement.classList.add('focused');
});
input.addEventListener('blur', function () {
if (!this.value) {
this.parentElement.classList.remove('focused');
}
});
if (input.value) {
input.parentElement.classList.add('focused');
}
});
}
});
function showError(input, message) {
input.classList.add('error');
const errorDiv = document.createElement('div');
errorDiv.className = 'error-message';
errorDiv.textContent = message;
errorDiv.style.color = 'var(--error-color)';
errorDiv.style.fontSize = '0.875rem';
errorDiv.style.marginTop = '0.25rem';
errorDiv.style.animation = 'slideDown 0.3s ease-out';
input.parentElement.appendChild(errorDiv);
}
(function () {
const cookieConsent = document.getElementById('cookie-consent');
const acceptBtn = document.getElementById('accept-cookies');
const declineBtn = document.getElementById('decline-cookies');
if (!cookieConsent) return;
const consent = localStorage.getItem('cookie-consent');
if (!consent) {
cookieConsent.style.display = 'block';
}
if (acceptBtn) {
acceptBtn.addEventListener('click', function () {
localStorage.setItem('cookie-consent', 'accepted');
cookieConsent.style.display = 'none';
if (typeof gtag !== 'undefined') {
gtag('event', 'cookie_consent', {
'event_category': 'Privacy',
'event_label': 'Accepted'
});
}
});
}
if (declineBtn) {
declineBtn.addEventListener('click', function () {
localStorage.setItem('cookie-consent', 'declined');
cookieConsent.style.display = 'none';
if (typeof gtag !== 'undefined') {
gtag('event', 'cookie_consent', {
'event_category': 'Privacy',
'event_label': 'Declined'
});
}
});
}
})();
(function () {
const faqQuestions = document.querySelectorAll('.faq-question');
faqQuestions.forEach(question => {
question.addEventListener('click', function () {
const faqItem = this.closest('.faq-item');
const isExpanded = this.getAttribute('aria-expanded') === 'true';
document.querySelectorAll('.faq-item').forEach(item => {
if (item !== faqItem) {
item.classList.remove('active');
item.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
}
});
if (isExpanded) {
faqItem.classList.remove('active');
this.setAttribute('aria-expanded', 'false');
} else {
faqItem.classList.add('active');
this.setAttribute('aria-expanded', 'true');
if (typeof gtag !== 'undefined') {
const questionText = this.querySelector('h3').textContent;
gtag('event', 'faq_view', {
'event_category': 'Engagement',
'event_label': questionText
});
}
}
});
});
})();
(function () {
const socialShare = document.getElementById('social-share');
const shareButtons = document.querySelectorAll('.social-share-btn');
if (window.location.pathname.includes('/blog/')) {
if (socialShare) {
socialShare.style.display = 'flex';
}
}
shareButtons.forEach(btn => {
btn.addEventListener('click', function () {
const platform = this.getAttribute('data-platform');
const url = encodeURIComponent(window.location.href);
const title = encodeURIComponent(document.title);
let shareUrl = '';
switch (platform) {
case 'twitter':
shareUrl = `https://twitter.com/intent/tweet?url=${url}&text=${title}`;
break;
case 'linkedin':
shareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${url}`;
break;
case 'email':
shareUrl = `mailto:?subject=${title}&body=${url}`;
break;
}
if (shareUrl) {
window.open(shareUrl, '_blank', 'width=600,height=400');
if (typeof gtag !== 'undefined') {
gtag('event', 'share', {
'method': platform,
'content_type': 'blog_post',
'item_id': window.location.pathname
});
}
}
});
});
})();
(function () {
const newsletterForms = document.querySelectorAll('.newsletter-form');
newsletterForms.forEach(form => {
form.addEventListener('submit', function (e) {
if (typeof gtag !== 'undefined') {
gtag('event', 'newsletter_signup', {
'event_category': 'Lead Generation',
'event_label': 'Newsletter Subscription'
});
}
});
});
})();
(function () {
let maxScroll = 0;
const scrollThresholds = [25, 50, 75, 90, 100];
window.addEventListener('scroll', function () {
const scrollPercent = Math.round(
(window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100
);
if (scrollPercent > maxScroll) {
scrollThresholds.forEach(threshold => {
if (scrollPercent >= threshold && maxScroll < threshold) {
if (typeof gtag !== 'undefined') {
gtag('event', 'scroll_depth', {
'event_category': 'Engagement',
'event_label': `${threshold}%`,
'value': threshold
});
}
}
});
maxScroll = scrollPercent;
}
});
})();
(function () {
let startTime = Date.now();
const trackInterval = 30000;
setInterval(function () {
const timeOnPage = Math.round((Date.now() - startTime) / 1000);
if (typeof gtag !== 'undefined' && timeOnPage % 30 === 0) {
gtag('event', 'time_on_page', {
'event_category': 'Engagement',
'event_label': '30 seconds',
'value': timeOnPage
});
}
}, trackInterval);
})();
(function () {
if (window.location.pathname === '/pricing') {
if (typeof gtag !== 'undefined') {
gtag('event', 'page_view', {
'event_category': 'Pricing',
'event_label': 'Pricing Page'
});
}
const pricingCards = document.querySelectorAll('.pricing-card');
pricingCards.forEach((card, index) => {
const cardTitle = card.querySelector('h3')?.textContent || `Pricing Tier ${index + 1}`;
const observer = new IntersectionObserver((entries) => {
entries.forEach(entry => {
if (entry.isIntersecting) {
if (typeof gtag !== 'undefined') {
gtag('event', 'pricing_card_view', {
'event_category': 'Pricing',
'event_label': cardTitle
});
}
observer.unobserve(entry.target);
}
});
}, { threshold: 0.5 });
observer.observe(card);
const ctaButton = card.querySelector('.pricing-cta');
if (ctaButton) {
ctaButton.addEventListener('click', function () {
if (typeof gtag !== 'undefined') {
gtag('event', 'pricing_cta_click', {
'event_category': 'Pricing',
'event_label': cardTitle,
'value': index + 1
});
}
});
}
});
}
})();
(function () {
'use strict';
function getThemePreference() {
const savedTheme = localStorage.getItem('theme');
if (savedTheme) {
return savedTheme;
}
return 'dark';
}
function applyTheme(theme) {
document.documentElement.setAttribute('data-theme', theme);
localStorage.setItem('theme', theme);
}
const currentTheme = getThemePreference();
applyTheme(currentTheme);
const themeToggle = document.querySelector('.theme-toggle');
if (themeToggle) {
themeToggle.addEventListener('click', function () {
const currentTheme = document.documentElement.getAttribute('data-theme');
const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
applyTheme(newTheme);
if (typeof gtag !== 'undefined') {
gtag('event', 'theme_change', {
'event_category': 'User Preference',
'event_label': newTheme
});
}
});
themeToggle.addEventListener('keydown', function (e) {
if (e.key === 'Enter' || e.key === ' ') {
e.preventDefault();
themeToggle.click();
}
});
}
if (window.matchMedia) {
const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
mediaQuery.addEventListener('change', function (e) {
if (!localStorage.getItem('theme')) {
applyTheme(e.matches ? 'dark' : 'light');
}
});
}
})();